import json
import os
import subprocess
import time
import urllib.request
import urllib.error
import urllib.parse
from datetime import datetime
from typing import Dict, Any, Optional


def get_api_base(url: str) -> str:
    if 'gitcode.com' in url:
        return "http/workspace/api.gitcode.com/api/v5"
    return "http/workspace/api.atomgit.com/api/v5"


def get_current_user(api_base: str, token: str) -> Dict[str, Any]:
    url = f"{api_base}/user"
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {token}"
    }

    req = urllib.request.Request(url, headers=headers)

    try:
        with urllib.request.urlopen(req, timeout=30) as response:
            return json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        raise Exception(f"获取用户信息失败: {e.code} {e.reason}")


def check_fork_exists(api_base: str, username: str, fork_name: str, token: str) -> bool:
    url = f"{api_base}/repos/{username}/{fork_name}"
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {token}"
    }

    req = urllib.request.Request(url, headers=headers)

    try:
        with urllib.request.urlopen(req, timeout=30) as response:
            return True
    except urllib.error.HTTPError as e:
        if e.code in (404, 403, 400):
            return False
        error_body = e.read().decode('utf-8') if e.fp else ''
        raise Exception(f"检查仓库失败: {e.code} {e.reason} - {error_body}")


def fork_repository(api_base: str, owner: str, repo: str, fork_name: str,
                    token: str) -> Dict[str, Any]:
    url = f"{api_base}/repos/{owner}/{repo}/forks"

    data = urllib.parse.urlencode({
        'name': fork_name,
        'default_branch_only': 'false'
    }).encode('utf-8')

    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/x-www-form-urlencoded"
    }

    req = urllib.request.Request(url, data=data, headers=headers, method='POST')

    try:
        with urllib.request.urlopen(req, timeout=60) as response:
            return json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        error_body = e.read().decode('utf-8') if e.fp else ''
        raise Exception(f"Fork 失败: {e.code} {e.reason} - {error_body}")


def generate_fork_name(repo_name: str) -> str:
    timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
    return f"{repo_name}-{timestamp}"


def clone_repo(clone_url: str, repo_dir: str, repo_name: str, logger=None) -> Optional[str]:
    repo_path = os.path.join(repo_dir, repo_name)

    if os.path.exists(repo_path):
        if logger:
            logger.info(f"  仓库已存在: {repo_path}")
        return repo_path

    os.makedirs(repo_dir, exist_ok=True)

    if logger:
        logger.info(f"  克隆仓库: {clone_url}")

    result = None
    for attempt in range(1, 3):
        result = subprocess.run(
            ['git', 'clone', clone_url, repo_path],
            capture_output=True,
            text=True
        )

        if result.returncode == 0:
            if logger:
                logger.info(f"  克隆成功")
            return repo_path

        if attempt == 1:
            if logger:
                logger.warning(f"  克隆失败 - {result.stderr.strip()}")
                logger.info(f"  等待 30 秒后重试...")
            time.sleep(30)
            if logger:
                logger.info(f"  重试克隆: {clone_url}")

    if logger:
        logger.error(f"  克隆失败 - {result.stderr.strip()}")
        logger.error(f"  克隆失败，结束执行")
    return None


def clone_repo_from_source(owner: str, repo: str, repo_dir: str,
                           issue_url: str = '', logger=None) -> Optional[str]:
    if 'gitcode.com' in issue_url:
        clone_url = f"http/workspace/gitcode.com/{owner}/{repo}.git"
    else:
        clone_url = f"http/workspace/atomgit.com/{owner}/{repo}.git"

    return clone_repo(clone_url, repo_dir, repo, logger=logger)


def download_patch(url: str, output_dir: str, cve_id: str, logger=None) -> Optional[str]:
    os.makedirs(output_dir, exist_ok=True)

    filename = f"backport-{cve_id}.patch"
    filepath = os.path.join(output_dir, filename)

    if os.path.exists(filepath):
        if logger:
            logger.info(f"      补丁已存在: {filename}")
        return filepath

    if logger:
        logger.info(f"      下载: {url}")

    req = urllib.request.Request(url, headers={'User-Agent': 'cve-deal/1.0'})

    try:
        with urllib.request.urlopen(req, timeout=60) as response:
            content = response.read()

            with open(filepath, 'wb') as f:
                f.write(content)

            if logger:
                logger.success(f"      下载成功: {filename}")
            return filepath
    except urllib.error.HTTPError as e:
        if logger:
            logger.error(f"      下载失败: {e.code} {e.reason}")
        return None
    except Exception as e:
        if logger:
            logger.error(f"      下载失败: {e}")
        return None

import os
import subprocess
import tempfile
from unittest import mock

import repo_manager


def _make_run_side_effect(clone_rc=0, revparse_rc=0, clone_stderr=''):
    """Create a side_effect callable for subprocess.run covering clone and rev-parse."""
    def side_effect(cmd, **kwargs):
        if 'clone' in cmd:
            return subprocess.CompletedProcess(
                args=cmd, returncode=clone_rc, stdout='', stderr=clone_stderr
            )
        if 'rev-parse' in cmd:
            return subprocess.CompletedProcess(
                args=cmd, returncode=revparse_rc, stdout='abc123\n', stderr=''
            )
        return subprocess.CompletedProcess(args=cmd, returncode=0, stdout='', stderr='')
    return side_effect


def test_clone_success_returns_path():
    """Normal successful clone with a valid HEAD should return the repo path."""
    with tempfile.TemporaryDirectory() as tmpdir:
        with mock.patch('subprocess.run', side_effect=_make_run_side_effect(
            clone_rc=0, revparse_rc=0
        )), mock.patch('time.sleep'):
            result = repo_manager.clone_repo(
                'http/workspace/example.com/repo.git', tmpdir, 'myrepo'
            )
            assert result is not None
            assert result == os.path.join(tmpdir, 'myrepo')

