import os
import subprocess
import tempfile
from unittest import mock

import repo_manager


def _make_run_side_effect(clone_rc=0, revparse_rc=0, clone_stderr=''):
    """Create a side_effect callable for subprocess.run covering clone and rev-parse."""
    def side_effect(cmd, **kwargs):
        if 'clone' in cmd:
            return subprocess.CompletedProcess(
                args=cmd, returncode=clone_rc, stdout='', stderr=clone_stderr
            )
        if 'rev-parse' in cmd:
            return subprocess.CompletedProcess(
                args=cmd, returncode=revparse_rc, stdout='abc123\n', stderr=''
            )
        return subprocess.CompletedProcess(args=cmd, returncode=0, stdout='', stderr='')
    return side_effect


def test_clone_empty_repo_returns_none():
    """When git clone returns 0 but the repo has no HEAD (empty), should return None."""
    with tempfile.TemporaryDirectory() as tmpdir:
        with mock.patch('subprocess.run', side_effect=_make_run_side_effect(
            clone_rc=0, revparse_rc=1
        )), mock.patch('time.sleep'):
            result = repo_manager.clone_repo(
                'http/workspace/example.com/repo.git', tmpdir, 'myrepo'
            )
            assert result is None


def test_existing_empty_directory_is_recloned():
    """A pre-existing empty target directory should be removed and re-cloned, not returned as-is."""
    with tempfile.TemporaryDirectory() as tmpdir:
        repo_path = os.path.join(tmpdir, 'myrepo')
        os.makedirs(repo_path)

        with mock.patch('subprocess.run', side_effect=_make_run_side_effect(
            clone_rc=0, revparse_rc=0
        )) as mock_run, mock.patch('time.sleep'):
            result = repo_manager.clone_repo(
                'http/workspace/example.com/repo.git', tmpdir, 'myrepo'
            )
            assert result == repo_path
            clone_calls = [
                c for c in mock_run.call_args_list
                if 'clone' in c.args[0]
            ]
            assert len(clone_calls) >= 1


def test_clone_failure_retries_four_times_by_default():
    """When every clone attempt fails, the default retry count should be 4."""
    with tempfile.TemporaryDirectory() as tmpdir:
        with mock.patch('subprocess.run') as mock_run, mock.patch('time.sleep'):
            mock_run.return_value = subprocess.CompletedProcess(
                args=[], returncode=1, stdout='', stderr='fatal: not found'
            )
            result = repo_manager.clone_repo(
                'http/workspace/example.com/repo.git', tmpdir, 'myrepo'
            )
            assert result is None
            clone_calls = [
                c for c in mock_run.call_args_list
                if 'clone' in c.args[0]
            ]
            assert len(clone_calls) == 4


def test_max_retries_parameter_accepted():
    """clone_repo should accept a max_retries keyword argument."""
    with tempfile.TemporaryDirectory() as tmpdir:
        with mock.patch('subprocess.run', side_effect=_make_run_side_effect(
            clone_rc=0, revparse_rc=0
        )), mock.patch('time.sleep'):
            result = repo_manager.clone_repo(
                'http/workspace/example.com/repo.git', tmpdir, 'myrepo', max_retries=1
            )
            assert result is not None
            assert result == os.path.join(tmpdir, 'myrepo')
